class Solution:
    def numTimesAllBlue(self, flips: List[int]) -> int:
        ans = mx = 0
        for i, f in enumerate(flips):
            mx = max(mx, f)
            if mx == i + 1:
                ans += 1
        return ans

c.cpp:
class Solution {
public:
    int numTimesAllBlue(vector<int>& flips) {
        int ans = 0, mx = 0;
        for (int i = 0; i < (int)flips.size(); ++i) {
            mx = max(mx, flips[i]);
            if (mx == i + 1) ans++;
        }
        return ans;
    }
};

